10	// The CLI's contract is its process behaviour — stdin, stdout, stderr and the
11	// exit code — so the tests drive a real subprocess rather than the module.
12	// A non-zero exit resolves rather than rejects; the rejection tests inspect it.
13	const runCli = (input: string): Promise<CliRun> =>
14	  new Promise((resolve, reject) => {
15	    const child = spawn("npx", ["tsx", "src/cli.ts"], { stdio: "pipe" });
16	
17	    let stdout = "";
18	    let stderr = "";
19	    child.stdout.on("data", (chunk) => (stdout += chunk));
20	    child.stderr.on("data", (chunk) => (stderr += chunk));
21	    child.on("error", reject);
22	    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));
23	
24	    child.stdin.write(input);
25	    child.stdin.end();
26	  });
