1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	// ---------------------------------------------------------------------------
42	// Shared arithmetic — used by both the premium and the claim side.
43	// ---------------------------------------------------------------------------
44	
45	// Percentages MUST go through this helper. Multiplying first and dividing by
46	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
47	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
48	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
49	// that drift becomes a whole extra G.
50	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
51	
52	// Money adds up the same way everywhere in this module — over items, over
53	// damages, over per-type groups. Naming the fold once keeps each call site
54	// about WHAT is being totalled rather than re-deriving how a sum is spelled.
55	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
56	  values.reduce((total, value) => total + amountOf(value), 0);
57	
58	// Both sides of the business tally things by type — the premium side groups
59	// items to find blocks, the claim side groups damages to check them against
60	// what is insured. The two differ only in WHICH field names the type
61	// (`type` on an Item, `itemType` on a Damage), so that is the parameter.
62	const tallyByType = <T>(values: T[], typeOf: (value: T) => string): Map<string, number> => {
63	  const counts = new Map<string, number>();
64	  for (const value of values) {
65	    const type = typeOf(value);
66	    counts.set(type, (counts.get(type) ?? 0) + 1);
67	  }
68	
69	  return counts;
70	};
71	
72	// Each item-level surcharge is "a percentage of this item's base premium, or
73	// nothing at all", so the condition is the only part that varies.
74	const percentOfWhen = (applies: boolean, amount: number, percent: number): number =>
75	  applies ? percentOf(amount, percent) : 0;
76	
77	// The MHPCO rounds in its own favour. That is ONE rule, but "its favour" points
78	// in opposite directions on the two sides of the business: a premium is money
79	// coming in, so a fraction rounds UP; a payout is money going out, so a fraction
80	// rounds DOWN. Naming both halves keeps the rule greppable and stops either call
81	// site from reading as an arbitrary choice of Math.ceil over Math.floor.
82	// They are deliberately two functions rather than one with a direction flag:
83	// `roundInMhpcosFavour(total, UP)` would hide at the call site exactly what the
84	// reader came there to learn.
85	const roundPremiumInMhpcosFavour = (amount: number): number => Math.ceil(amount);
86	const roundPayoutInMhpcosFavour = (amount: number): number => Math.floor(amount);
87	
88	// ---------------------------------------------------------------------------
89	// Premium side — quoting a policy.
90	// ---------------------------------------------------------------------------
91	
92	const PROCESSING_FEE = 5;
93	
94	const FIRST_INSURANCE_PERCENT = 10;
95	
96	const BASE_PREMIUMS: Record<string, number> = {
97	  sword: 100,
98	  amulet: 60,
99	  staff: 80,
100	  potion: 40,
101	  rune: 25,
102	  moonstone: 25,
103	};
104	
105	const BLOCK_SIZE = 3;
106	const BLOCK_BASE_PREMIUM = 60;
107	
108	const countByType = (items: Item[]): Map<string, number> =>
109	  tallyByType(items, ({ type }) => type);
110	
111	// Priced per GROUP of alike items, not per item: a group of exactly BLOCK_SIZE
112	// buys the flat block rate instead of the unit price. Deliberately not named
113	// after BASE_PREMIUMS[type] — that constant is the unit price, this is the
114	// group's premium, and conflating the two is what the block rule invites.
115	const premiumForAlikeGroup = (type: string, count: number): number =>
116	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
117	
118	const policyBasePremium = (items: Item[]): number =>
119	  sumOf([...countByType(items)], ([type, count]) => premiumForAlikeGroup(type, count));
120	
121	const CURSE_PERCENT = 50;
122	
123	const HIGH_ENCHANTMENT_PERCENT = 30;
124	const HIGH_ENCHANTMENT_THRESHOLD = 5;
125	
126	const itemSurcharge = (item: Item): number => {
127	  const base = BASE_PREMIUMS[item.type];
128	  const curseSurcharge = percentOfWhen(item.cursed === true, base, CURSE_PERCENT);
129	  const highEnchantmentSurcharge = percentOfWhen(
130	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
131	    base,
132	    HIGH_ENCHANTMENT_PERCENT,
133	  );
134	
135	  return curseSurcharge + highEnchantmentSurcharge;
136	};
137	
138	const itemSurcharges = (items: Item[]): number => sumOf(items, itemSurcharge);
139	
140	// Every modifier is a percentage of a base premium, and they are SUMMED rather
141	// than compounded: the spec's worked example reads
142	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
143	// so the first-insurance 10 % is taken on the policy base, not on the
144	// curse-inflated amount.
145	const LOYALTY_PERCENT = 20;
146	const LOYALTY_THRESHOLD_YEARS = 2;
147	
148	const FOLLOW_UP_PERCENT = 15;
149	
150	// Rejections surface as exceptions; the CLI turns them into a non-zero exit
151	// and a stderr line.
152	const rejectUnknownTypes = (items: Item[]): void => {
153	  for (const { type } of items) {
154	    if (!(type in BASE_PREMIUMS)) throw new Error(`The MHPCO does not insure a ${type}.`);
155	  }
156	};
157	
158	const quote = ({ items }: QuoteStep, customer: Customer, isFollowUp: boolean): StepResult => {
159	  rejectUnknownTypes(items);
160	
161	  const policyBase = policyBasePremium(items);
162	
163	  // Surcharges add to the policy base, discounts subtract from it. Both are
164	  // percentages OF THE POLICY BASE (never of each other) — see the note above.
165	  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
166	  const loyaltyDiscount = percentOfWhen(
167	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
168	    policyBase,
169	    LOYALTY_PERCENT,
170	  );
171	
172	  const followUpDiscount = percentOfWhen(isFollowUp, policyBase, FOLLOW_UP_PERCENT);
173	
174	  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge;
175	  const discounts = loyaltyDiscount + followUpDiscount;
176	  const total = policyBase + surcharges - discounts + PROCESSING_FEE;
177	
178	  return { premium: roundPremiumInMhpcosFavour(total) };
179	};
180	
181	// ---------------------------------------------------------------------------
182	// Claim side — settling a payout against an open policy.
183	// ---------------------------------------------------------------------------
184	
185	const INSURANCE_VALUES: Record<string, number> = {
186	  sword: 1000,
187	  amulet: 600,
188	  staff: 800,
189	  potion: 400,
190	  rune: 250,
191	  moonstone: 250,
192	};
193	
194	const DEDUCTIBLE = 100;
195	const CAP_MULTIPLIER = 2;
196	
197	interface Policy {
198	  items: Item[];
199	  remainingCap: number;
200	}
201	
202	// The cap is a multiple of the INSURED values of the items — the unit values,
203	// untouched by anything that moved the premium (block rate, curse, loyalty).
204	const insuranceSum = (items: Item[]): number =>
205	  sumOf(items, ({ type }) => INSURANCE_VALUES[type]);
206	
207	const openPolicy = (items: Item[]): Policy => ({
208	  items,
209	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
210	});
211	
212	// Settling a claim both answers the step and moves the policy on: successive
213	// claims draw down the same cap. Rather than writing through the caller's
214	// Policy, `claim` returns the policy it leaves behind, so the depletion is
215	// visible at the one place that owns the registry.
216	// The claim-side enchantment threshold (8) is deliberately NOT the premium-side
217	// one (5): a sword can be enchanted enough to cost more to insure without being
218	// enchanted enough to have its damage halved.
219	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
220	const HALVED_REIMBURSEMENT_PERCENT = 50;
221	
222	// How much of a damage amount the policy covers, BEFORE the deductible — the
223	// caller subtracts that. Special clauses are written as guards in precedence
224	// order: the first one that matches decides, so a clause that must win over
225	// another is simply written above it.
226	const coveredAmount = (damage: Damage, item: Item): number => {
227	  const isHighlyEnchanted = (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD;
228	  if (isHighlyEnchanted) return percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT);
229	
230	  return damage.amount;
231	};
232	
233	// What a single damage entry is worth on its own: the covered amount that the
234	// item's clauses allow, less the deductible that every damaged item carries.
235	// Takes the already-resolved item rather than finding it: by the time any
236	// arithmetic runs, `resolveDamagedItems` has established that every damage has
237	// an item, so there is no absent case left for this function to answer for.
238	const payoutForDamage = (damage: Damage, item: Item): number =>
239	  coveredAmount(damage, item) - DEDUCTIBLE;
240	
241	// The two limits the incident total is squeezed between, named so each call site
242	// says which way it bites rather than leaving the reader to decode a bare
243	// Math.max/Math.min. Both are floors and ceilings on the SAME quantity, applied
244	// in this order: nothing below zero, nothing above what the cap still holds.
245	const neverBelowZero = (amount: number): number => Math.max(0, amount);
246	const neverAboveRemainingCap = (amount: number, remainingCap: number): number =>
247	  Math.min(amount, remainingCap);
248	
249	// Rejected outright rather than left to the payout's zero floor, which would
250	// quietly turn a nonsensical claim into a payout of nothing.
251	const rejectNegativeAmounts = (damages: Damage[]): void => {
252	  for (const { itemType, amount } of damages) {
253	    if (amount < 0) {
254	      throw new Error(`A ${itemType} cannot suffer a negative damage of ${amount} G.`);
255	    }
256	  }
257	};
258	
259	// A policy answers only for what it insures. Pairs each damage with the item it
260	// hits, rejecting the whole claim if any damage has no such item.
261	//
262	// Hoisted out of the payout arithmetic to sit with its sibling guards: "the
263	// whole claim is rejected, never partially paid" is a claim-level contract, and
264	// running every rejection up front is what makes that structural rather than a
265	// consequence of which order the payout fold happens to visit entries in.
266	// Returning the pairs rather than void is what lets the guard move here AND
267	// keeps the arithmetic cast-free — "the item is present" is carried in the
268	// return type instead of re-asserted downstream with `as Item`.
269	const resolveDamagedItems = (damages: Damage[], items: Item[]): [Damage, Item][] =>
270	  damages.map((damage) => {
271	    const item = items.find(({ type }) => type === damage.itemType);
272	    if (!item) throw new Error(`This policy does not cover a ${damage.itemType}.`);
273	
274	    return [damage, item];
275	  });
276	
277	// A policy insuring one sword cannot answer for two damaged swords. The whole
278	// claim is rejected rather than paid in part.
279	const rejectOverCountedDamages = (damages: Damage[], items: Item[]): void => {
280	  const insured = countByType(items);
281	
282	  for (const [itemType, claimed] of tallyByType(damages, ({ itemType }) => itemType)) {
283	    if (claimed > (insured.get(itemType) ?? 0)) {
284	      throw new Error(`This policy does not cover ${claimed} items of type ${itemType}.`);
285	    }
286	  }
287	};
288	
289	const claim = (
290	  { incident }: ClaimStep,
291	  policy: Policy,
292	): { result: StepResult; policy: Policy } => {
293	  // Every way a claim can be rejected outright, all of them before any payout
294	  // arithmetic runs — a rejected claim is never partially paid. Order matters
295	  // between the last two: a damage to a type the policy does not insure at all
296	  // must report exactly that, rather than being caught by the over-count guard
297	  // as "0 insured, 1 claimed" and misreported as a miscount.
298	  rejectNegativeAmounts(incident.damages);
299	  const damagedItems = resolveDamagedItems(incident.damages, policy.items);
300	  rejectOverCountedDamages(incident.damages, policy.items);
301	
302	  // Per-damage amounts stay fractional: the rounding wraps the SUMMED total, not
303	  // each entry, and happens before the cap clamp below so remainingCap stays whole.
304	  const incidentTotal = roundPayoutInMhpcosFavour(
305	    sumOf(damagedItems, ([damage, item]) => payoutForDamage(damage, item)),
306	  );
307	
308	  // A damage below the deductible pays nothing; the MHPCO is stingy, not a
309	  // debt collector. Only the TOTAL is held at zero — whether a below-deductible
310	  // entry should offset a sibling entry in the same incident is unspecified.
311	  const claimable = neverBelowZero(incidentTotal);
312	
313	  // The policy pays at most what is left of its cap; the excess is simply lost.
314	  const payout = neverAboveRemainingCap(claimable, policy.remainingCap);
315	  const remainingCap = policy.remainingCap - payout;
316	
317	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
318	};
319	
320	// The follow-up discount is about contract number, so only quote steps count —
321	// interleaved claim steps must not make the next quote look like a follow-up.
322	const isFollowUpQuote = (steps: Step[], index: number): boolean =>
323	  steps.slice(0, index).some((earlier) => earlier.op === "quote");
324	
325	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
326	  // Policies opened by quote steps, keyed by the step index a later claim cites.
327	  // Claims draw the cap down, so this registry is the one piece of carried state.
328	  const policies = new Map<number, Policy>();
329	
330	  const results = steps.map((step, index) => {
331	    if (step.op === "quote") {
332	      policies.set(index, openPolicy(step.items));
333	
334	      return quote(step, customer, isFollowUpQuote(steps, index));
335	    }
336	
337	    const settled = claim(step, policies.get(step.policy) as Policy);
338	    policies.set(step.policy, settled.policy);
339	
340	    return settled.result;
341	  });
342	
343	  return { results };
344	};
